153	 *
154	 * Inside the TTL the cached body is returned without touching the network.
155	 * Outside it — or with nothing cached — the network is asked, and the answer
156	 * replaces the copy. If that request fails and a stale copy exists, the stale
157	 * copy wins: a week-old description or yesterday's catalogue is far better than
158	 * an error page, and the caller has no way to draw anything without one.
159	 *
160	 * Degrades to a plain fetch wherever Cache Storage isn't available (it needs a
161	 * secure context, so `file://` and plain http get the uncached path).
162	 *
163	 * @param {string} url
164	 * @param {number} ttlMs how long a downloaded copy may be reused
165	 * @param {(err: unknown, url: string) => void} [onNote] optional log sink
166	 */
167	export async function cachedFetchJson(url, ttlMs, onNote, validate) {
168	  const note = onNote || (() => {});
169	  const check = (data) => {
170	    if (validate && !validate(data)) throw new Error(`${url} failed validation`);
171	    return data;
172	  };
173	  let cache = null;
174	  try {
175	    if (typeof caches !== "undefined") cache = await caches.open(CACHE_NAME);
176	  } catch {
177	    cache = null;
178	  }
179	  if (!cache) return check(await fetchJson(url));
180	
181	  const fetchedAt = fetchStamps()[url];
182	  if (fetchedAt && Date.now() - fetchedAt < ttlMs) {
183	    const hit = await readCached(cache, url, validate, note);
184	    if (hit) return hit.data;
185	  }
186	
187	  try {
188	    const res = await fetch(url);
189	    if (!res.ok) throw new Error(`HTTP ${res.status} fetching ${url}`);
190	    // Read the payload BEFORE touching Cache Storage, and hand the cache a fresh
191	    // Response built from the text rather than a clone of this one. Cache.put()
192	    // consumes the body it is given, and clone() tees a single stream into two —
193	    // so a put that dies partway (quota, an evicted cache, a dropped connection)
194	    // errors the response we still have to read. Writing first therefore let a
195	    // failed *cache write* discard a *successful download*: that is how the
196	    // planner lost availability.min.json and drew every show as unavailable
197	    // (#309). The cache is an optimisation; the payload is the point.
198	    const text = await res.text();
199	    const data = check(JSON.parse(text));
200	    try {
201	      await cache.put(url, new Response(text, { headers: { "Content-Type": "application/json" } }));
202	      stampFetch(url);
203	    } catch (err) {
204	      note(err, url);
205	    }
206	    return data;
207	  } catch (err) {
208	    // Same read as above, and the same rule: a stale copy that can't be read (or
209	    // that validation rejects) is no copy at all. It must not become the error
210	    // the caller sees — that would report a cache problem for what is really a
211	    // network one, and send them chasing the wrong thing.
212	    const stale = await readCached(cache, url, validate, note);
