280	 * The catalogue is cached for four days and the sidecar for one, so they are
281	 * routinely joined across generations, and a few misses are the honest cost of
282	 * that: a show that added or dropped a date since the catalogue was packed
283	 * finds no status, which is exactly what the date-and-time naming scheme was
284	 * designed to do. Real drift over four days is a fraction of a percent.
285	 *
286	 * A systematic key change is a different animal. #274 corrected every start
287	 * time by an hour, and the next day's sidecar matched 6% of the previous day's
288	 * catalogue — 94% of the festival status-unknown, drawn as unavailable (#309).
289	 * Nothing between 6% and 99% is a state we can tell a coherent story about, so
290	 * the line sits where it separates drift from breakage rather than where it
291	 * splits the difference. */
292	const MIN_STATUS_COVERAGE = 0.9;
293	
294	/**
295	 * Do these two files describe the same festival?
296	 *
297	 * Two independent answers, because they fail in different places. The
298	 * fingerprint is exact and cheap and settles it outright — but only for a
299	 * sidecar new enough to carry one, which a cached copy predating that field
300	 * won't. Coverage is the fallback: approximate, but it reads the join itself
301	 * rather than a claim about it, so it also catches whatever the fingerprint
302	 * hasn't thought of.
303	 *
304	 * @returns {{ok: boolean, why?: string}}
305	 */
306	function joinIsSound(wire, availability, catalogue) {
307	  const stamped = availability && typeof availability.k === "string";
308	  if (stamped) {
309	    const mine = joinFingerprint(wire);
310	    if (mine !== availability.k) {
311	      return { ok: false, why: `catalogue ${mine} vs availability ${availability.k}` };
312	    }
313	  }
314	
315	  let performances = 0;
316	  let withStatus = 0;
317	  for (const show of catalogue) {
318	    for (const perf of show.performances || []) {
319	      performances++;
320	      if (perf.status) withStatus++;
321	    }
322	  }
323	  if (performances === 0) return { ok: true }; // an empty catalogue is a different problem
324	  const coverage = withStatus / performances;
325	  if (coverage < MIN_STATUS_COVERAGE) {
326	    return {
327	      ok: false,
328	      why: `only ${withStatus} of ${performances} performances (${Math.round(coverage * 100)}%) ` +
329	           "carry a ticket status",
330	    };
331	  }
332	  return { ok: true };
333	}
334	
335	/**
336	 * The three files the planner is built from, joined — refetched once from source
337	 * if the copies we were given don't agree with each other.
338	 *
339	 * All three are required. Availability used to be allowed to fail on the theory
340	 * that status-unknown is a state the grid already draws — it isn't. An empty
341	 * status reads as not-bookable everywhere downstream (isAvailable, segClass,
342	 * laneStatus), so continuing without the sidecar doesn't degrade the planner, it
343	 * inverts it: every performance turns red and every show reports "No dates", for
344	 * a festival that is very much on sale (#309).
345	 *
346	 * The retry is the substance. A generation disagreement is not a network failure
347	 * and not a corrupt file — it is two perfectly good files that have drifted
348	 * apart on their separate TTLs, and the fix is simply to go and get today's, so
349	 * that is what happens. Only if freshly-downloaded copies *still* disagree is
350	 * this a real failure, and then it belongs in the error panel: at that point we
351	 * genuinely don't know what's bookable, and a wrong plan is worse than no plan.
352	 */
353	async function loadCatalogue() {
354	  for (const attempt of [1, 2]) {
355	    const [wire, lookups, availability] = await Promise.all([
356	      cachedFetchJson(DATA_URL, CATALOGUE_TTL_MS, noteCache, isCatalogue),
357	      cachedFetchJson(VENUES_URL, LOOKUPS_TTL_MS, noteCache, isLookups),
358	      cachedFetchJson(AVAILABILITY_URL, AVAILABILITY_TTL_MS, noteCache, isAvailabilitySidecar),
359	    ]);
360	    const catalogue = rehydrateShows(wire, lookups, YEAR, availability);
361	    const verdict = joinIsSound(wire, availability, catalogue);
362	    if (verdict.ok) return { lookups, catalogue };
363	
364	    if (attempt === 2) {
365	      throw new Error(
366	        `the catalogue and the ticket availability don't match (${verdict.why})`
367	      );
368	    }
369	    // Drop both and go again. Which of the two is stale isn't knowable from
