1	// Tests for the TTL data cache (shared/data-cache.js).
2	//
3	// This is the whole of the site's freshness policy — GitHub Pages won't let us
4	// set Cache-Control per file, so the decision of how long each data file may be
5	// reused lives here. The behaviours worth pinning down are the ones that fail
6	// quietly in a browser: a TTL that doesn't actually suppress the network, an
7	// expiry that doesn't actually re-fetch, and the fallbacks (no Cache Storage, a
8	// dead network, a full quota) that must still hand the caller its data.
9	//
10	// Cache Storage and localStorage don't exist in Node, so both are stubbed. The
11	// stubs are deliberately thin: `caches.open` returning a `{match, put}` pair is
12	// the entire surface the module uses.
13	
14	import { test } from "node:test";
15	import assert from "node:assert/strict";
16	
17	import { cachedFetchJson, fetchJson, DAY_MS } from "../data-cache.js";
18	
19	// --- Stubs ----------------------------------------------------------------
20	
21	function installStubs({ bodies = {}, failFetch = false, noCaches = false,
22	                        putThrows = false, putPoisonsBody = false, now = 1_000_000 } = {}) {
23	  const calls = { fetch: [], put: [], delete: [] };
24	  const store = new Map();       // url -> serialized body (the Cache Storage stand-in)
25	  const corruptCached = new Set(); // urls whose stored body reads back as an error
26	  const local = new Map();       // the localStorage stand-in
27	
28	  const saved = {
29	    fetch: globalThis.fetch,
30	    caches: globalThis.caches,
31	    localStorage: globalThis.localStorage,
32	    now: Date.now,
33	  };
34	
35	  globalThis.fetch = async (url) => {
36	    calls.fetch.push(url);
37	    if (failFetch) throw new Error("offline");
38	    return response(bodies[url]);
39	  };
40	
41	  /* A response and its clones share one body, the way a real one does: clone()
42	   * tees a single stream into two, so whatever kills one branch kills both.
43	   * `stream.dead` is that shared fate — see the putPoisonsBody test for why
44	   * modelling it matters. */
45	  function response(body, stream = { dead: false }) {
46	    const text = JSON.stringify(body);
47	    const read = async () => {
48	      if (stream.dead) throw new TypeError("Failed to fetch");
49	      return text;
50	    };
51	    return {
52	      ok: true, status: 200, stream,
53	      text: read,
54	      json: async () => JSON.parse(await read()),
55	      clone: () => response(body, stream),
56	    };
57	  }
58	
59	  globalThis.caches = noCaches ? undefined : {
60	    open: async () => ({
61	      match: async (url) => {
62	        if (!store.has(url)) return undefined;
63	        // A stored body that can't be read back: a write truncated by a dropped
64	        // connection, an entry evicted mid-read, a storage-layer error.
65	        if (corruptCached.has(url)) {
66	          return { ok: true, status: 200, stream: {},
67	                   text: async () => { throw new TypeError("Failed to read cached response"); },
68	                   json: async () => { throw new TypeError("Failed to read cached response"); },
69	                   clone() { return this; } };
70	        }
71	        return response(store.get(url));
72	      },
73	      delete: async (url) => { calls.delete.push(url); corruptCached.delete(url); return store.delete(url); },
74	      put: async (url, res) => {
75	        calls.put.push(url);
76	        // Cache.put() reads the body it is handed. A write that dies partway
77	        // leaves that stream — and so its twin — unreadable.
78	        if (putPoisonsBody) {
79	          if (res.stream) res.stream.dead = true;
80	          throw new TypeError("Cache.put() encountered a network error");
81	        }
82	        if (putThrows) throw new Error("quota exceeded");
83	        store.set(url, await res.json());
84	      },
85	    }),
86	  };
87	
88	  globalThis.localStorage = {
89	    getItem: (k) => (local.has(k) ? local.get(k) : null),
90	    setItem: (k, v) => local.set(k, v),
91	  };
92	
93	  const clock = { now };
94	  Date.now = () => clock.now;
95	
96	  return {
97	    calls,
98	    clock,
99	    seed: (url, body) => store.set(url, body),
100	    corrupt: (url) => corruptCached.add(url),
101	    stamps: () => JSON.parse(local.get("edfringe.data.fetched.v1") || "{}"),
102	    restore: () => {
103	      globalThis.fetch = saved.fetch;
104	      globalThis.caches = saved.caches;
105	      globalThis.localStorage = saved.localStorage;
106	      Date.now = saved.now;
107	    },
108	  };
109	}
110	
111	const URL_A = "data/normalized/availability.min.json";
112	
113	// --- Tests ----------------------------------------------------------------
114	
115	test("inside the TTL the cached copy is served without touching the network", async () => {
116	  const s = installStubs({ bodies: { [URL_A]: { v: 1 } } });
117	  try {
118	    assert.deepEqual(await cachedFetchJson(URL_A, DAY_MS), { v: 1 });
119	    assert.equal(s.calls.fetch.length, 1, "the first call must go to the network");
120	
121	    // Most of a day later, still inside the TTL.
122	    s.clock.now += DAY_MS - 1;
123	    assert.deepEqual(await cachedFetchJson(URL_A, DAY_MS), { v: 1 });
124	    assert.equal(s.calls.fetch.length, 1, "a hit inside the TTL must not re-fetch");
125	  } finally {
126	    s.restore();
127	  }
128	});
129	
130	test("past the TTL the network is asked again and the copy is replaced", async () => {
131	  const bodies = { [URL_A]: { v: 1 } };
132	  const s = installStubs({ bodies });
133	  try {
134	    await cachedFetchJson(URL_A, DAY_MS);
135	    s.clock.now += DAY_MS + 1;
136	    bodies[URL_A] = { v: 2 }; // the festival moved on
137	    assert.deepEqual(await cachedFetchJson(URL_A, DAY_MS), { v: 2 });
138	    assert.equal(s.calls.fetch.length, 2);
139	
140	    // ...and the replacement is what the next in-TTL read gets.
141	    assert.deepEqual(await cachedFetchJson(URL_A, DAY_MS), { v: 2 });
142	    assert.equal(s.calls.fetch.length, 2);
143	  } finally {
144	    s.restore();
145	  }
146	});
147	
148	test("each url carries its own clock, so a long TTL can't shelter a short one", async () => {
149	  // The catalogue is held for days while availability is held for one. They
150	  // share a cache; they must not share an expiry.
151	  const catalogue = "data/normalized/shows.min.json";
152	  const s = installStubs({ bodies: { [catalogue]: [1], [URL_A]: { v: 1 } } });
153	  try {
154	    await cachedFetchJson(catalogue, 4 * DAY_MS);
155	    await cachedFetchJson(URL_A, DAY_MS);
156	    assert.equal(s.calls.fetch.length, 2);
157	
158	    s.clock.now += DAY_MS + 1; // past availability's TTL, well inside the catalogue's
159	    await cachedFetchJson(catalogue, 4 * DAY_MS);
160	    await cachedFetchJson(URL_A, DAY_MS);
161	    assert.deepEqual(s.calls.fetch, [catalogue, URL_A, URL_A],
162	      "only the expired url may be re-fetched");
163	  } finally {
164	    s.restore();
165	  }
166	});
167	
168	test("a failed re-fetch falls back to the stale copy rather than throwing", async () => {
169	  const s = installStubs({ bodies: { [URL_A]: { v: 1 } } });
170	  try {
171	    await cachedFetchJson(URL_A, DAY_MS);
172	    s.restore();
173	
174	    // Same store, now with a dead network.
175	    const offline = installStubs({ failFetch: true, now: 1_000_000 + DAY_MS + 1 });
176	    offline.seed(URL_A, { v: 1 });
177	    // The stamp map was reset with the stubs, so this is the has-nothing-fresh
178	    // path: it tries the network, fails, and must still answer.
179	    const notes = [];
180	    try {
181	      assert.deepEqual(
182	        await cachedFetchJson(URL_A, DAY_MS, (err, url) => notes.push(url)),
183	        { v: 1 }, "yesterday's availability beats an error page");
184	      assert.deepEqual(notes, [URL_A], "the fallback must be reported to the caller's log");
185	    } finally {
186	      offline.restore();
187	    }
188	  } finally {
189	    s.restore();
190	  }
191	});
192	
193	test("a failed fetch with nothing cached throws — there is nothing to draw", async () => {
194	  const s = installStubs({ failFetch: true });
195	  try {
196	    await assert.rejects(() => cachedFetchJson(URL_A, DAY_MS), /offline/);
197	  } finally {
198	    s.restore();
199	  }
200	});
201	
202	test("without Cache Storage it degrades to a plain fetch, every time", async () => {
203	  // file:// and plain http get no Cache Storage. The page must still work.
204	  const s = installStubs({ bodies: { [URL_A]: { v: 1 } }, noCaches: true });
205	  try {
206	    assert.deepEqual(await cachedFetchJson(URL_A, DAY_MS), { v: 1 });
207	    assert.deepEqual(await cachedFetchJson(URL_A, DAY_MS), { v: 1 });
208	    assert.equal(s.calls.fetch.length, 2, "no cache means no reuse, not an error");
209	  } finally {
210	    s.restore();
211	  }
212	});
213	
214	test("a cache write that fails still returns the data, and doesn't stamp it fresh", async () => {
215	  // Private mode / full quota. The caller got its answer; the only cost is that
216	  // the next visit re-fetches.
217	  const s = installStubs({ bodies: { [URL_A]: { v: 1 } }, putThrows: true });
218	  try {
219	    const notes = [];
220	    assert.deepEqual(await cachedFetchJson(URL_A, DAY_MS, (err, url) => notes.push(url)), { v: 1 });
221	    assert.deepEqual(notes, [URL_A]);
222	    assert.deepEqual(await cachedFetchJson(URL_A, DAY_MS), { v: 1 });
223	    assert.equal(s.calls.fetch.length, 2, "an unstamped url must be re-fetched");
224	  } finally {
225	    s.restore();
226	  }
227	});
228	
229	test("a cache write that dies mid-body must not cost the caller its download", async () => {
230	  // The regression behind the "every show is sold out" planner (#309). Cache.put()
231	  // consumes the body it is given, and clone() tees one stream into two — so a put
232	  // that fails partway errors the response we still have to read. Writing to the
233	  // cache before reading the payload therefore threw away a download that had
234	  // already succeeded: availability.min.json went missing, every performance
235	  // became status-unknown, and the grid drew all 4,122 shows as unavailable.
236	  //
237	  // The cache write may fail. Losing the data because of it may not.
238	  const s = installStubs({ bodies: { [URL_A]: { v: 1 } }, putPoisonsBody: true });
239	  try {
240	    const notes = [];
241	    assert.deepEqual(
242	      await cachedFetchJson(URL_A, DAY_MS, (err, url) => notes.push(url)), { v: 1 },
243	      "the payload was downloaded intact — a failed cache write must not discard it");
244	    assert.deepEqual(notes, [URL_A], "the write that failed is still worth logging");
245	  } finally {
246	    s.restore();
247	  }
248	});
249	
250	test("an unreadable cached copy falls through to the network instead of throwing", async () => {
251	  // The production failure in #309, and the half of it the first fix missed. The
252	  // network panel for the broken page showed NO request for any data file: all
253	  // four were served from Cache Storage. So the read that failed was the *cache*
254	  // read, and that path had no fall-through — a truncated or unreadable entry
255	  // propagated straight out, and because the stamp stayed fresh it failed
256	  // identically on every load for the whole TTL. A day for availability; four
257	  // days for the catalogue.
258	  const s = installStubs({ bodies: { [URL_A]: { v: 1 } } });
259	  try {
260	    await cachedFetchJson(URL_A, DAY_MS);            // populate + stamp
261	    assert.equal(s.calls.fetch.length, 1);
262	    s.corrupt(URL_A);                                // the entry goes bad in place
263	
264	    const notes = [];
265	    assert.deepEqual(await cachedFetchJson(URL_A, DAY_MS, (err, url) => notes.push(url)), { v: 1 },
266	      "a cached copy we can't read is a miss, not a failure");
267	    assert.equal(s.calls.fetch.length, 2, "the network must be asked when the cache can't answer");
268	    assert.deepEqual(notes, [URL_A], "the unreadable entry is worth logging");
269	    assert.deepEqual(s.calls.delete, [URL_A], "and worth evicting, so it can't fail again tomorrow");
270	  } finally {
271	    s.restore();
272	  }
273	});
274	
275	test("a cached copy of the wrong shape is refetched rather than trusted", async () => {
276	  // The other way a cache read produces no data and no error: an entry from an
277	  // older generation of the file. It parses, so nothing throws — it simply joins
278	  // to nothing downstream, which the planner drew as "every show unavailable".
279	  // The sidecar carries a `v` for exactly this; the caller knows the schema, so
280	  // the caller gets to reject the copy.
281	  const isSidecar = (d) => Boolean(d) && d.v === 1 && d.a && Object.keys(d.a).length > 0;
282	  const s = installStubs({ bodies: { [URL_A]: { v: 1, a: { SHOW: {} } } } });
283	  try {
284	    s.seed(URL_A, { version: 1, shows: {} });        // a previous generation's shape
285	    localStorage.setItem("edfringe.data.fetched.v1", JSON.stringify({ [URL_A]: 1_000_000 }));
286	
287	    const notes = [];
288	    assert.deepEqual(
289	      await cachedFetchJson(URL_A, DAY_MS, (err, url) => notes.push(url), isSidecar),
290	      { v: 1, a: { SHOW: {} } }, "a copy that fails validation must not be served");
291	    assert.equal(s.calls.fetch.length, 1, "it goes to the network instead");
292	    assert.deepEqual(s.calls.delete, [URL_A]);
293	    assert.deepEqual(s.stamps(), { [URL_A]: 1_000_000 },
294	      "and the fresh copy is stamped in its place");
295	  } finally {
296	    s.restore();
297	  }
298	});
299	
300	test("a validator that rejects the network's answer too surfaces the error", async () => {
301	  // Belt and braces: if neither the cache nor the network can produce something
302	  // usable, that is a real failure and must be raised, not papered over.
303	  const s = installStubs({ bodies: { [URL_A]: { v: 0 } } });
304	  try {
305	    await assert.rejects(
306	      () => cachedFetchJson(URL_A, DAY_MS, undefined, (d) => d.v === 1),
307	      /failed validation/);
308	  } finally {
309	    s.restore();
310	  }
311	});
312	
313	test("an unreadable stale copy doesn't mask the network error behind it", async () => {
314	  const s = installStubs({ bodies: { [URL_A]: { v: 1 } } });
315	  try {
316	    await cachedFetchJson(URL_A, DAY_MS);
317	    s.restore();
318	
319	    const offline = installStubs({ failFetch: true, now: 1_000_000 + DAY_MS + 1 });
320	    offline.seed(URL_A, { v: 1 });
321	    offline.corrupt(URL_A);
322	    try {
323	      // The fallback read fails too — the caller must hear about the network,
324	      // not about the cache.
325	      await assert.rejects(() => cachedFetchJson(URL_A, DAY_MS, () => {}), /offline/);
326	    } finally {
327	      offline.restore();
328	    }
329	  } finally {
330	    s.restore();
331	  }
332	});
333	
334	test("fetchJson turns a non-ok response into an error naming the url", async () => {
335	  const saved = globalThis.fetch;
336	  globalThis.fetch = async () => ({ ok: false, status: 404, json: async () => ({}) });
337	  try {
338	    await assert.rejects(() => fetchJson("data/venues.json"), /HTTP 404 fetching data\/venues\.json/);
339	  } finally {
340	    globalThis.fetch = saved;
341	  }
342	});
343

