205	 * the map and list. Only the current day is fetched, so the payload stays light.
206	 *
207	 * "Today" is the fringe day, 06:00 → 06:00 (shared/fringe-day.js), so the file
208	 * also carries tomorrow's small hours — the late shows someone at 23:50 is
209	 * actually looking for. Their `start` comes through extended ("24:30" for
210	 * 00:30), which is what keeps them sorting and comparing after 23:00 rather
211	 * than before 06:00. */
212	async function loadShows() {
213	  // The day this load is for. Boot starts one for the day the page opened on,
214	  // and the geolocation fix can adopt the real clock — a different day — and
215	  // start a second while the first is still in flight. Both assign state.shows,
216	  // so whichever lands last wins, and if that is the superseded one the page
217	  // ends up holding one day's shows against another day's clock: every show
218	  // reads as unreachable and the page says "nothing reachable in the next
219	  // couple of hours", with nothing wrong that anything logs.
220	  const wantedDay = NOW.fringeDate;
221	  try {
222	    // Both are validated on the way out of the cache: a stored copy from an older
223	    // generation parses fine and then reads as an empty festival, with nothing
224	    // logged anywhere (#309). venues.json in particular is the same Cache Storage
225	    // entry the planner uses — one bad copy would take out both pages.
226	    const [lookups, day] = await Promise.all([
227	      cachedFetchJson("data/venues.json", LOOKUPS_TTL_MS, noteCache,
228	        (d) => Boolean(d) && typeof d.venues === "object" && d.venues !== null),
229	      cachedFetchJson(`data/days/${NOW.fringeDate}.json`, DAY_TTL_MS, noteCache,
230	        (d) => Array.isArray(d)),
231	    ]);
232	    if (NOW.fringeDate !== wantedDay) return;
233	    // The shared lookup file carries the venue map plus the global rooms/genres
234	    // lists that the day records index into. Fetched once.
