1	// Renders one screen case to a PNG buffer — the single pixel source shared by
2	// the comparing runner (screen.test.js) and the refresh lane (refresh.js), so
3	// a golden can never be produced one way and checked another.
4	"use strict";
5	
6	const { newPage, ORIGIN } = require("./harness/browser");
7	const { nowReady, planReady, scrollToTop } = require("./case-helpers");
8	const { makeTools } = require("./capture-tools");
9	
10	async function renderScreenCase(testCase) {
11	  const { page, context } = await newPage({
12	    viewport: testCase.viewport,
13	    localStorage: testCase.localStorage,
14	    geolocation: testCase.geolocation,
15	    failData: testCase.failData,
16	    timezone: testCase.timezone,
17	    colorScheme: testCase.colorScheme,
18	    advanceableClock: testCase.advanceableClock,
19	  });
20	  // What the page itself said. A case that comes up empty because a fetch or a
21	  // cache read threw looks, from the outside, exactly like one that rendered an
22	  // empty state on purpose — and the app says which in its console and nowhere
23	  // else. Kept to the last few, since the whole point is to read it in a log.
24	  const spoken = [];
25	  const remember = (line) => {
26	    spoken.push(line.slice(0, 200));
27	    if (spoken.length > 10) spoken.shift();
28	  };
29	  page.on("console", (m) => {
30	    if (m.type() === "error" || m.type() === "warning") remember(`${m.type()}: ${m.text()}`);
31	  });
32	  page.on("pageerror", (e) => remember(`pageerror: ${e.message}`));
33	  try {
34	    return await driveAndCapture(page, testCase);
35	  } catch (err) {
36	    // A case that fails in CI cannot be re-run by the reader, and its failure
37	    // artifacts go to a host a session cannot reach — so the error carries what
38	    // the page actually showed at the moment it gave up.
39	    err.message += `\n\nPage state when this failed:\n${await describePage(page)}`;
40	    err.message += `\n\nWhat the page said:\n${spoken.length ? spoken.join("\n") : "(nothing)"}`;
41	    throw err;
42	  } finally {
43	    await context.close();
44	  }
45	}

