// --- data-dir-is-generator-output: every committed file under data/ must be
// something scraper/normalize.py produces ---

const cleanDataTree = {
  "site/data/venues.json": "",
  "data/shows.json": "",
  "data/normalized/shows.json": "",
  "site/data/normalized/shows.min.json": "",
  "site/data/normalized/descriptions.min.json": "",
  "site/data/days/index.json": "",
  "site/data/days/2026-08-07.json": "",
  "js/app.js": "",
};

test("a data/ holding only normalizer output ⇒ no findings", () => {
  const out = dataDirRule.run(textCtx(cleanDataTree));
  assert.deepEqual(out, [], `expected no findings, got ${JSON.stringify(out, null, 2)}`);
});

test("the named scraper input data/prices.json is allowed; a lookalike is not", () => {
  // prices.json is the one committed file under data/ that normalize.py READS
  // rather than writes (scraper/fetch_prices.py produces it). It is allowed by
  // name, so a second file cannot ride in on its shape.
  assert.deepEqual(dataDirRule.run(textCtx({ ...cleanDataTree, "data/prices.json": "" })), []);
  const out = dataDirRule.run(textCtx({ ...cleanDataTree, "data/prices.backup.json": "" }));
  assert.equal(out.length, 1);
  assert.equal(out[0].file, "data/prices.backup.json");
  assert.ok(out[0].fix.includes("data/prices.json"),
    "the fix must name the inputs that ARE allowed, so the reader can tell the two apart");
});

test("a second scraper's named output is allowed; a lookalike beside it is not", () => {
  // data/jerusalem/ is the one-shot Jerusalem scrape's output, written by
  // scraper/jerusalem/fetch.py. Named, like the price cache, so the exemption
  // covers that file and not the directory it lives in.
  assert.deepEqual(dataDirRule.run(textCtx({ ...cleanDataTree, "site/data/jerusalem/shows.json": "" })), []);
  const out = dataDirRule.run(textCtx({ ...cleanDataTree, "site/data/jerusalem/notes.json": "" }));
  assert.equal(out.length, 1);
  assert.equal(out[0].file, "site/data/jerusalem/notes.json");
  assert.ok(out[0].fix.includes("site/data/jerusalem/shows.json"),
    "the fix must name the outputs that ARE allowed, so the reader can tell the two apart");
});

test("the published tree is scanned too — a hand-made file under site/data/ is reported", () => {
  // The rule covers two roots, and this is the one that matters most: a file the
  // normalizer does not write, sitting under site/data/, is SERVED to visitors.
  // Without this case every negative fixture here sits under data/, so dropping
  // site/data/ from the scan leaves the whole suite green.
  const out = dataDirRule.run(textCtx({ ...cleanDataTree, "site/data/hand/notes.json": "" }));
  assert.equal(out.length, 1);
  assert.equal(out[0].file, "site/data/hand/notes.json");
});

test("a force-added Jerusalem page cache gets the un-track fix, not a delete", () => {
  const out = dataDirRule.run(textCtx({ ...cleanDataTree, "data/jerusalem/raw_pages/salakh.html": "" }));
  assert.equal(out.length, 1);
  assert.match(out[0].fix, /git rm --cached data\/jerusalem\/raw_pages\/salakh\.html/);
});

test("a probe's output committed under data/ is reported", () => {
  // The exact regression this guards: a throwaway probe's answer is parked in
  // data/ as if it were data, where nothing regenerates it and the next
  // refresh-shows run neither maintains nor removes it.
  const out = dataDirRule.run(textCtx({ ...cleanDataTree, "data/ticket-status-enum.json": "" }));
  assert.equal(out.length, 1);
  assert.equal(out[0].rule, "edfringe-data-dir-is-generator-output");
  assert.equal(out[0].severity, "blocking");
  assert.equal(out[0].file, "data/ticket-status-enum.json");
  assert.match(out[0].what, /is not something a generator in this repo produces/);
  assert.ok(out[0].fix.includes("normalize.py"), "the fix must name the producer to fix instead");

